WITH recent_shipments AS (SELECT *, DATE_SUB(delivered_date, 87) AS delivered_date_minus_87d FROM shipments WHERE MONTH(shipped_date) IN (4, 7, 9) AND cost >= 94), cost_bucket_summary AS (SELECT CASE WHEN cost >= 97 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END AS cost_bucket, AVG(cost) AS avg_cost, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list FROM recent_shipments GROUP BY CASE WHEN cost >= 97 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END) SELECT * FROM cost_bucket_summary WHERE avg_cost > 61 ORDER BY 2 DESC;
